-- Run as database administrator against a disposable DB or in this rollback-only transaction.
-- Models PostgREST database roles; does NOT test JWT signature verification or HTTP middleware.
BEGIN;
SET LOCAL statement_timeout = '30s';
SET LOCAL lock_timeout = '2s';
CREATE TEMP TABLE security_results (test text, passed boolean, observed text, unchanged boolean);
CREATE FUNCTION pg_temp.snapshot() RETURNS jsonb LANGUAGE sql AS $$
 SELECT jsonb_build_object(
 'exams',(SELECT jsonb_agg(to_jsonb(e) ORDER BY exam_id) FROM public.exams e WHERE institution_id::text LIKE 'a0212026-%'),
 'questions',(SELECT jsonb_agg(to_jsonb(q) ORDER BY question_id) FROM public.questions q WHERE exam_id IN (SELECT exam_id FROM public.exams WHERE institution_id::text LIKE 'a0212026-%')),
 'members',(SELECT jsonb_agg(to_jsonb(m) ORDER BY institution_id,user_id) FROM public.institution_members m WHERE institution_id::text LIKE 'a0212026-%'),
 'reports',(SELECT jsonb_agg(to_jsonb(r) ORDER BY student_report_id) FROM public."studentReport" r WHERE exam_id IN (SELECT exam_id FROM public.exams WHERE institution_id::text LIKE 'a0212026-%')),
 'events',(SELECT jsonb_agg(to_jsonb(v) ORDER BY to_jsonb(v)::text) FROM public.qualify_events v WHERE student_report_id IN (SELECT student_report_id FROM public."studentReport" WHERE exam_id::text LIKE 'a0212026-%')),
 'banks',(SELECT jsonb_agg(to_jsonb(b) ORDER BY id) FROM public.qualify_named_banks b WHERE institution_id::text LIKE 'a0212026-%'),
 'institutions',(SELECT jsonb_agg(to_jsonb(i) ORDER BY id) FROM public.institutions i WHERE id::text LIKE 'a0212026-%'),
 'audit',(SELECT jsonb_agg(to_jsonb(a) ORDER BY to_jsonb(a)::text) FROM public.institution_audit a WHERE institution_id::text LIKE 'a0212026-%'));
$$;
CREATE FUNCTION pg_temp.check_case(label text, actor uuid, db_role text, statement text, denial boolean DEFAULT false)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER AS $$
DECLARE before_state jsonb; after_state jsonb; ok boolean; code text; detail text;
BEGIN
 before_state := pg_temp.snapshot();
 -- Every individual request is rolled back, including unexpected successful attacks.
 BEGIN
  PERFORM set_config('request.jwt.claim.sub',coalesce(actor::text,''),true);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role',db_role,
    'user_metadata',jsonb_build_object('role','platform_owner','isAdmin',true))::text,true);
  EXECUTE format('SET LOCAL ROLE %I',db_role);
  BEGIN
   EXECUTE statement INTO ok;
   code := '00000';
  EXCEPTION WHEN OTHERS THEN
   GET STACKED DIAGNOSTICS code=RETURNED_SQLSTATE, detail=MESSAGE_TEXT;
   ok := denial AND (code='42501' OR (code='P0001' AND detail ~* '(cannot|only|not allowed|not authorized|invalid|not found|suspended|close|locked|must|denied|access required|already using|session expired|already closed)'));
  END;
  RESET ROLE;
  after_state := pg_temp.snapshot();
  RAISE EXCEPTION USING ERRCODE='ZT001',MESSAGE='rollback test request';
 EXCEPTION WHEN SQLSTATE 'ZT001' THEN NULL;
 END;
 INSERT INTO security_results VALUES(label,coalesce(ok,false) AND (NOT denial OR before_state=after_state),code || coalesce(': '||detail,''),before_state=after_state);
END;
$$;
