SELECT * FROM security_results ORDER BY passed,test;
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM security_results WHERE passed IS NOT TRUE) THEN
  RAISE EXCEPTION 'Security matrix failed: %', (SELECT string_agg(test, ', ') FROM security_results WHERE passed IS NOT TRUE);
 END IF;
END $$;
